using System.Security.Cryptography;

public static class PasswordKdf
{
    // tune this based on perf tests
    private const int Iterations = 210_000;
    private const int SaltSize = 16;     // 128-bit
    private const int KeySize = 32;      // 256-bit
    private const string Algo = "PBKDF2-SHA256";
    private const int Version = 1;

    public static string Hash(string password)
    {
        byte[] salt = RandomNumberGenerator.GetBytes(SaltSize);

        byte[] key = Rfc2898DeriveBytes.Pbkdf2(
            password,
            salt,
            Iterations,
            HashAlgorithmName.SHA256,
            KeySize);

        // Store: v:algo:iter:saltB64:hashB64
        return $"{Version}:{Algo}:{Iterations}:{Convert.ToBase64String(salt)}:{Convert.ToBase64String(key)}";
    }

    public static bool Verify(string password, string stored)
    {
        var parts = stored.Split(':');
        if (parts.Length != 5) return false;

        if (!int.TryParse(parts[0], out var version) || version != Version) return false;
        var algo = parts[1];
        if (algo != Algo) return false;

        if (!int.TryParse(parts[2], out var iterations)) return false;

        byte[] salt = Convert.FromBase64String(parts[3]);
        byte[] expected = Convert.FromBase64String(parts[4]);

        byte[] actual = Rfc2898DeriveBytes.Pbkdf2(
            password,
            salt,
            iterations,
            HashAlgorithmName.SHA256,
            expected.Length);

        return CryptographicOperations.FixedTimeEquals(actual, expected);
    }
}
